'use strict';

const fs = require('fs');
const path = require('path');

const REGISTRY_PATH = path.resolve(__dirname, '../style-registry.json');
const BUILD_OUTPUT_PATH = path.resolve(__dirname, '../style-registry-built.json');

function buildStyleRegistry() {
  const raw = fs.readFileSync(REGISTRY_PATH, 'utf-8');
  const registry = JSON.parse(raw);

  // Validate required sections
  if (!registry.tokens || !registry.components) {
    throw new Error('style-registry.json must contain tokens and components sections');
  }

  // Build the output with only approved tokens
  const output = {
    tokens: { ...registry.tokens },
    components: { ...registry.components }
  };

  fs.writeFileSync(BUILD_OUTPUT_PATH, JSON.stringify(output, null, 2));
  return output;
}

module.exports = { buildStyleRegistry };

