  line-height: 1.4;
}

.mtd-quiz-banner-cta.score-button {
  flex: 0 0 auto;
  min-height: 48px;
  padding: 12px 24px;
  border-radius: 999px;
  font-family: inherit;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.mtd-quiz-section {
  background: var(--theme-background-color);
  padding: 32px 0 48px;
  scroll-margin-top: 80px;
}

.mtd-quiz-frame {
  display: block;
  width: 100%;
  min-height: 640px;
  border: 0;
  border-radius: 16px;
  background: var(--theme-background-color);
}

/* Variant A: the quiz in a dialog opened from the hero CTA. */
.mtd-quiz-modal[hidden] {
  display: none;
}

.mtd-quiz-modal {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.mtd-quiz-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
}

.mtd-quiz-modal-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  width: min(1200px, 100%);
  max-height: calc(100vh - 48px);
  overflow: hidden;
  border-radius: 16px;
  background: var(--theme-background-color);
}

.mtd-quiz-modal-head {
